<?php
declare(strict_types=1);namespace App;use PDO;final class SystemRepository{public function __construct(public readonly PDO$db){}public function one(string$sql,array$args=[]):array{$s=$this->db->prepare($sql);$s->execute($args);$r=$s->fetch();if(!$r)throw new ApiException(404,'not_found','Resource not found.');return$r;}public function rows(string$sql,array$args=[]):array{$s=$this->db->prepare($sql);$s->execute($args);return$s->fetchAll();}public function server(int$id):array{return$this->one('SELECT * FROM servers WHERE id=?',[$id]);}public function audit(int$actor,?int$server,string$action,string$details):void{$this->db->prepare('INSERT INTO audit_events(actor_id,server_id,action,details,created_at) VALUES(?,?,?,?,?)')->execute([$actor,$server,$action,$details,gmdate(DATE_ATOM)]);}}
